registry_candidates ['ADR-0004', 'ADR-0008', 'ADR-0006', 'ADR-0010', 'ADR-0005', 'ADR-0009']
[
 {
  "section": "interfaces",
  "name": "change_notification",
  "entry_yaml": "  - contract: change_notification\n    status: active           # ADR-0004 is Proposed\n    pattern: direct_call     # kernel-owned observer registry invoking method Callables; not engine signals\n    producer: command-simulation-layer (kernel P5 and frame-end delivery)\n    consumers:\n      - presentation-subscribers\n      - input-surface-subscribers\n      - projector-subscribers\n      - diagnostic-subscribers\n      - replication-subscriber (VS-B)\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    signal_signature: \"NotifyFacet.subscribe(cls: int, block_id: StringName, handler: Callable, name: StringName) -> SubscriptionHandle; handler(batch: ChangeBatch, ctx: NotifyContext) -> CompletionToken with return ctx.complete() last; ChangeBatch {block_id, tick, first_tick, is_all, count, event_count, key(i), has(key), event(i)}; DirtyAccumulator.absorb(batch); Kernel.deliver_frame_end() is the last step of TickDriver.frame\"\n    referenced_by:\n      - docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28\n    revised: \"\""
 },
 {
  "section": "interfaces",
  "name": "dirty_key_marking",
  "entry_yaml": "  - contract: dirty_key_marking\n    status: active           # ADR-0004 is Proposed\n    pattern: direct_call\n    producer: block-owners (inside a mutator, after scope.open_for)\n    consumers:\n      - command-simulation-layer\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    signal_signature: \"scope.mark_dirty(block_id: StringName, key: int) -> void; scope.emit_event(block_id: StringName, kind: int, a0..a5: int = 0) -> void; BlockRegistrar.register_key_space(desc: KeySpaceDescriptor) -> void (BOOTING only; kind_ids, kind_names, event_ids, event_names, quiet_writes_allowed); keys and events marked in INIT and RESTORE scopes are discarded\"\n    referenced_by:\n      - docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n      - docs/architecture/adr-0003-state-block-registry-and-owner-contract.md\n    added: 2026-10-28\n    revised: \"\""
 },
 {
  "section": "api_decisions",
  "name": "notification_transport",
  "entry_yaml": "  - purpose: notification_transport\n    status: active           # ADR-0004 is Proposed; KRN-LAT-02 notify cost gates acceptance\n    api: \"kernel-owned subscription registry; per-block subscriptions; Callable.call(batch, ctx) on method Callables guarded by is_valid(); subscribe and unsubscribe applied at the next delivery boundary\"\n    not: \"engine signal or Signal.emit for kernel to subscriber notification; connect() on a kernel object; lambda or .bind() handlers; a per-tick copy of the subscriber list\"\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    reason: \"The handler must return the completion token (INCOMPLETE per subscriber), delivery has two cadences by class, DEAD_SUBSCRIBER must be counted, and per-block filtering keeps a quiet tick at zero calls; cost does not separate the options (probed 2026-10-28, 155 vs 157 ns per call)\"\n    referenced_by:\n      - docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28\n    revised: \"\""
 },
 {
  "section": "api_decisions",
  "name": "dirty_key_encoding",
  "entry_yaml": "  - purpose: dirty_key_encoding\n    status: active           # ADR-0004 is Proposed\n    api: \"int key = (KIND << 32) | id, KIND 1..0x7FFF declared per block, id 0..0xFFFFFFFF; PackedInt64Array buffers filled with NO_KEY = 0x7FFFFFFFFFFFFFFF; ALL is the batch flag is_all, never a key value; capacity = MAX_DIRTY_KEYS sized at the registry freeze, runtime changes lower only\"\n    not: \"String, StringName, float or Variant keys; PackedInt32Array key buffers; a Dictionary used as the dirty set; ALL as a reserved key value; raising MAX_DIRTY_KEYS above the sized capacity at run time\"\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    reason: \"Every owner GDD already writes (KIND << 32) | id; 47 bits need 64-bit storage; a native has() scan on a preallocated array dedupes without allocating (probed 2026-10-28: 160-230 ns per mark, 52 us for 256 distinct keys, OBJECT_COUNT flat)\"\n    referenced_by:\n      - docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28\n    revised: \"\""
 },
 {
  "section": "state_ownership",
  "name": "touch_serial_and_notification_buffers",
  "entry_yaml": "  - state: touch_serial_and_notification_buffers\n    status: active           # ADR-0004 is Proposed\n    owner_system: command-simulation-layer (kernel)\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    interface: \"touch_serial[block] written by every granted scope.open_for and read through Kernel.touch_serial(block_index); per-block tick and frame KeyBufs, the NotifyEvent pool and the subscription lists are kernel-internal (H1 allow-list: registries and diagnostics); subscribers see only ChangeBatch facades valid for the duration of one handler call\"\n    write_access: kernel-only (mutators reach the buffers only through scope.mark_dirty and scope.emit_event)\n    referenced_by:\n      - docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28\n    revised: \"\""
 },
 {
  "section": "performance_budgets",
  "name": "kernel_p5_notify",
  "entry_yaml": "  - system: kernel_p5_notify\n    status: active           # ADR-0004 is Proposed\n    budget_ms: 0.25\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    notes: \"PROPOSAL pending KRN-LAT-02, not a GDD number: P5 plus frame-end delivery P99 on a release export on RM-DESKTOP and RM-DECK for 12 dirty blocks, 40 subscriptions, a 38-key Graph cascade and 4 events; inside the 4.0 ms one-tick frame simulation budget\"\n    referenced_by:\n      - docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28\n    revised: \"\""
 },
 {
  "section": "forbidden_patterns",
  "name": "kernel_signal_notification",
  "entry_yaml": "  - pattern: kernel_signal_notification\n    status: active           # ADR-0004 is Proposed\n    description: \"No engine signal carries kernel-to-subscriber change notification: src/kernel declares no signal for it, nothing connect()s to a kernel object, and subscribers register only through NotifyFacet.subscribe. Engine signals remain legal inside presentation.\"\n    why: \"A signal returns nothing (no completion token, no per-subscriber INCOMPLETE), has no class cadence or block filter, and hides dead subscribers; OQ-4 decided on semantics.\"\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28"
 },
 {
  "section": "forbidden_patterns",
  "name": "lambda_or_retained_batch_subscriber",
  "entry_yaml": "  - pattern: lambda_or_retained_batch_subscriber\n    status: active           # ADR-0004 is Proposed\n    description: \"A subscriber handler is a standard method Callable on a long-lived object with the signature (batch, ctx) -> CompletionToken; never a lambda or .bind() result, and never retains a ChangeBatch, a kernel key buffer or an event object past the handler call (copy into a DirtyAccumulator).\"\n    why: \"Probed 2026-10-28: lambdas and bind results are custom Callables whose get_object() does not identify the owner and which keep self alive; the batch is a reused facade re-armed every delivery.\"\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28"
 },
 {
  "section": "forbidden_patterns",
  "name": "non_integer_or_undeclared_dirty_key",
  "entry_yaml": "  - pattern: non_integer_or_undeclared_dirty_key\n    status: active           # ADR-0004 is Proposed\n    description: \"A dirty key is an int (KIND << 32) | id built from integers, KIND declared in the block's KeySpaceDescriptor; never a String, StringName, float or Variant, never an id above 32 bits, never key 0 or NO_KEY; events carry only ints and never state.\"\n    why: \"No String is built per key per run (Graph LS-20, ADR-LSG-06); NO_KEY is the buffer sentinel; notifications carry no state (CR-10).\"\n    adr: docs/architecture/adr-0004-change-notification-and-dirty-keys.md\n    added: 2026-10-28"
 },
 {
  "section": "referenced_by_update",
  "name": "write_outside_writescope_or_setter_dirty",
  "entry_yaml": "forbidden_patterns / write_outside_writescope_or_setter_dirty: add to referenced_by (the entry has no referenced_by field today): docs/architecture/adr-0004-change-notification-and-dirty-keys.md  # mark_dirty requires a prior open_for in the same scope use; INIT and RESTORE marks are discarded"
 },
 {
  "section": "referenced_by_update",
  "name": "owner_callable_contract",
  "entry_yaml": "interfaces / owner_callable_contract: add to referenced_by: docs/architecture/adr-0004-change-notification-and-dirty-keys.md  # subscriber handlers are (batch, ctx: NotifyContext) -> CompletionToken"
 },
 {
  "section": "referenced_by_update",
  "name": "block_registration",
  "entry_yaml": "interfaces / block_registration: add to referenced_by: docs/architecture/adr-0004-change-notification-and-dirty-keys.md  # BlockRegistrar gains register_key_space(KeySpaceDescriptor)"
 },
 {
  "section": "referenced_by_update",
  "name": "presentation_submit_without_handle",
  "entry_yaml": "forbidden_patterns / presentation_submit_without_handle: add to referenced_by: docs/architecture/adr-0004-change-notification-and-dirty-keys.md  # subscribing confers no submit right; this ADR reconciles kernel GDD AC ~L1014 to it"
 }
]
