 },
 {
  "file": "design/gdd/command-simulation-layer.md (Tuning Knobs)",
  "old": "(no entry)",
  "new": "Add MAX_SUBSCRIPTIONS (96, 32-256, Boot), MAX_EVENTS_PER_TICK (64, 16-256, Boot), build flag AUDIT_EVERY_TICK (test and dev builds), with safe ranges and failure modes; MAX_DIRTY_KEYS: runtime changes may only lower it (raising above the sized capacity is KNOB_REFUSED)."
 },
 {
  "file": "design/gdd/life-support-graph.md (LS-20)",
  "old": "[UNV that the kernel's key type is Variant; if it is String, the family strings are the encoding and nothing else changes]",
  "new": "The kernel's key type is a 64-bit int (ADR-0004); composite family ids such as L/<loop>/<anchor> are packed by the Graph into the 32-bit id."
 },
 {
  "file": "design/gdd/web-map-and-transit.md (WM-31 consumers column)",
  "old": "Audio, Attention, Horror (event consumers)",
  "new": "Attention and Horror read web.state's view in their hooks (a block or hook owner never subscribes, CR-10); events reach presentation subscribers and are not a sim input."
 },
